begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select is(private.set_winner(11,9),'a','eleven with two-point margin wins');
select is(private.set_winner(10,10),null::text,'deuce remains open');
select is(private.set_winner(11,10),null::text,'one-point margin is insufficient');
select is(private.set_winner(1000000002,1000000000),'a','deuce has no sport-specific point cap');
select throws_ok($$select private.set_winner(12,0)$$,'22023','Invalid terminal set score','cannot keep scoring after a set already ended');
select throws_ok($$select private.set_winner(-1,0)$$,'22023','Invalid set score','negative points rejected');
create temp table scoring_fixture(state jsonb);
insert into scoring_fixture values('{"initial_server":"b","sets":[{"a":0,"b":0}],"timeouts":{"a":false,"b":false}}');
select is(private.score_summary((select state from scoring_fixture))->>'server','b','initial server comes from judge choice');
update scoring_fixture set state=private.score_transition(state,'{"kind":"point","side":"a"}');
select is(private.score_summary((select state from scoring_fixture))->>'server','b','server remains for first point');
update scoring_fixture set state=private.score_transition(state,'{"kind":"point","side":"b"}');
select is(private.score_summary((select state from scoring_fixture))->>'server','a','serve changes after two points');
update scoring_fixture set state=jsonb_set(state,'{sets}','[{"a":10,"b":10}]');
select is(private.score_summary((select state from scoring_fixture))->>'server','b','deuce starts with initial set server');
update scoring_fixture set state=private.score_transition(state,'{"kind":"point","side":"a"}');
select is(private.score_summary((select state from scoring_fixture))->>'server','a','serve changes every point at deuce');
update scoring_fixture set state=private.score_transition(state,'{"kind":"point","side":"a"}');
select is(private.score_summary((select state from scoring_fixture))->>'set_number','2','winning deuce opens next set');
select is(private.score_summary((select state from scoring_fixture))->>'server','a','first server alternates between sets');
update scoring_fixture set state=private.score_transition(state,'{"kind":"undo_point","side":"a"}');
select is(private.score_summary((select state from scoring_fixture))->>'points_a','11','undo reopens just-completed set');
select is(private.score_summary((select state from scoring_fixture))->>'set_number','1','undo removes empty next-set projection');
update scoring_fixture set state=private.score_transition(state,'{"kind":"timeout","side":"a"}');
select throws_ok($$select private.score_transition((select state from scoring_fixture),'{"kind":"timeout","side":"a"}')$$,'22023','Timeout unavailable','second timeout for same player denied');
update scoring_fixture set state=private.score_transition(state,'{"kind":"undo_set"}');
select is((select state->'timeouts'->>'a' from scoring_fixture),'true','score undo does not restore a used timeout');
select is(private.score_summary((select state from scoring_fixture))->>'points_a','0','undo set clears its points');
select throws_ok($$select private.score_summary('{"initial_server":"a","sets":[{"a":11,"b":0}],"timeouts":{"a":false,"b":false}}')$$,'22023','Next set required','canonical ongoing state needs next set');
update scoring_fixture set state='{"initial_server":"a","sets":[{"a":11,"b":0},{"a":11,"b":0},{"a":11,"b":0}],"timeouts":{"a":false,"b":false}}';
select is(private.score_summary((select state from scoring_fixture))->>'winner','a','three sets finish singles');
select throws_ok($$select private.score_transition((select state from scoring_fixture),'{"kind":"point","side":"b"}')$$,'22023','Singles already finished','normal point cannot extend a completed singles');
select throws_ok($$select private.score_transition((select state from scoring_fixture),'{"kind":"undo_point","side":"b"}')$$,'22023','Invalid undo point','completed-set undo targets actual winning point');
select is(private.score_summary(private.score_transition((select state from scoring_fixture),'{"kind":"undo_point","side":"a"}'))->>'winner',null::text,'pure correction can reopen result; future RPC must enforce authority');
select is(private.team_outcome('["a","b","a","a",null]')->>'winner','a','team winner needs three singles');
select is(private.team_outcome('["a","b",null,null,null]')->>'winner',null::text,'two completed singles do not finish match');
select throws_ok($$select private.team_outcome('["a","a","a","a"]')$$,'22023','Invalid team results','four singles wins cannot be accepted');
select is(private.elo_pair(1000,1000,'a',32),' {"a":1016,"b":984}'::jsonb,'standard equal-rating Elo');
select is(private.elo_pair(0,0,'a',32),'{"a":16,"b":0}'::jsonb,'minimum rating is zero');
select is(private.elo_pair(1000,1000,'a',1),'{"a":1001,"b":1000}'::jsonb,'round each individual result to whole rating');
select is(private.elo_pair(1000,1000,'a',250000),'{"a":126000,"b":0}'::jsonb,'formula has no provisional 100000-point ceiling');
select is(private.elo_pair(1234,500,'b',32,true),'{"a":1234,"b":500}'::jsonb,'automatic losses leave ratings unchanged');
select throws_ok($$select private.elo_pair(1000,1000,'a',0)$$,'22023','Invalid Elo inputs','nonpositive K rejected');
select throws_ok($$select private.elo_pair(1000.5,1000,'a',32)$$,'22023','Invalid Elo inputs','whole rating precision is explicit');
set local role authenticated;
select throws_ok($$select private.score_transition('{}','{}')$$,'42501',null,'staff cannot bypass future scoring RPC via private evaluator');
select throws_ok($$select private.elo_pair(1000,1000,'a',32)$$,'42501',null,'private Elo evaluator grants no rating-write bypass');
reset role;
set local role anon;
select throws_ok($$select private.score_summary('{}')$$,'42501',null,'anonymous cannot execute private rule helpers');
reset role;
select * from finish();
rollback;
